#if MACOS_SURFACE_CHECKS
import AppKit

// Contract checks for the macOS page/card surface pairing in `SMTheme`.
//
// The bug these exist to prevent: `windowBackgroundColor` behind
// `controlBackgroundColor` looks like the obvious "page behind card" pairing,
// but AppKit resolves BOTH to the same value — #FFFFFF in Aqua, #1E1E1E in
// Dark Aqua. Every card in the app was therefore drawn in exactly the page
// color and disappeared into it, in both appearances, with only a hairline
// border left to suggest a card was ever there.
//
// A compiler cannot catch that, and a screenshot only catches it on the one
// appearance you happened to look at. So the pairing is asserted here against
// the *live* system colors, in every appearance the app can be rendered in —
// which also means a future macOS that collapses another pair fails loudly
// instead of silently flattening the UI again.

private struct CheckFailure: Error {
    let message: String
}

private var checksRun = 0

/// Perceived lightness of a resolved color, 0…255.
private func luminance(_ color: NSColor) -> Double {
    guard let s = color.usingColorSpace(.sRGB) else { return -1 }
    return (0.299 * s.redComponent + 0.587 * s.greenComponent + 0.114 * s.blueComponent) * 255
}

private func describe(_ color: NSColor) -> String {
    guard let s = color.usingColorSpace(.sRGB) else { return "unresolvable" }
    return String(
        format: "#%02X%02X%02X",
        Int((s.redComponent * 255).rounded()),
        Int((s.greenComponent * 255).rounded()),
        Int((s.blueComponent * 255).rounded())
    )
}

/// The minimum step that still reads as a distinct surface. macOS's own
/// grouped pairing (`underPageBackgroundColor` behind white) is 9/255, so
/// anything at or above that is in system-idiomatic territory; below ~6 the
/// card stops being findable without hunting for its border.
private let minimumSeparation: Double = 6

private func expectDistinctSurfaces(
    appearanceName: NSAppearance.Name,
    page: @autoclosure () -> NSColor,
    card: @autoclosure () -> NSColor
) throws {
    guard let appearance = NSAppearance(named: appearanceName) else {
        // A future SDK could retire an appearance; skipping is correct, but it
        // must be visible rather than silently reducing coverage.
        print("  note: appearance \(appearanceName.rawValue) is unavailable, skipped")
        return
    }

    var failure: String?
    appearance.performAsCurrentDrawingAppearance {
        let pageColor = page()
        let cardColor = card()
        let separation = luminance(cardColor) - luminance(pageColor)

        checksRun += 1
        if separation < minimumSeparation {
            failure = """
            \(appearanceName.rawValue): page \(describe(pageColor)) and card \(describe(cardColor)) \
            differ by \(String(format: "%.1f", separation))/255, below the \(Int(minimumSeparation)) \
            needed for the card to read as a distinct surface \
            (negative means the card is darker than the page, which reads as recessed)
            """
        }
    }

    if let failure {
        throw CheckFailure(message: failure)
    }
}

private let appearances: [NSAppearance.Name] = [
    .aqua,
    .darkAqua,
    .accessibilityHighContrastAqua,
    .accessibilityHighContrastDarkAqua,
]

private func isDark(_ appearance: NSAppearance) -> Bool {
    appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
}

private func runChecks() throws {

    // MARK: The pairing SMTheme actually ships
    //
    // Mirrors `SMTheme.pageBackground` / `SMTheme.cardFill`. The shell half of
    // this script pins the source to these same colors, so the two cannot drift
    // apart without one of them failing.

    for name in appearances {
        try expectDistinctSurfaces(
            appearanceName: name,
            page: NSAppearance.current.map { isDark($0) ? NSColor.windowBackgroundColor : .underPageBackgroundColor } ?? .windowBackgroundColor,
            card: NSAppearance.current.map { isDark($0) ? NSColor.underPageBackgroundColor : .controlBackgroundColor } ?? .controlBackgroundColor
        )
    }

    // MARK: The trap itself, asserted directly
    //
    // If these ever start differing, the simpler pairing becomes available and
    // `SMTheme` can be simplified — but until then, anyone reaching for the
    // "obvious" combination needs to find out here rather than from a user.

    for name in appearances {
        guard let appearance = NSAppearance(named: name) else { continue }
        var collapsed = false
        appearance.performAsCurrentDrawingAppearance {
            collapsed = abs(luminance(NSColor.windowBackgroundColor) - luminance(NSColor.controlBackgroundColor)) < minimumSeparation
        }
        checksRun += 1
        guard collapsed else {
            throw CheckFailure(message: """
            \(name.rawValue): windowBackgroundColor and controlBackgroundColor now differ. \
            That is good news — re-check whether SMTheme still needs its per-appearance pairing \
            and simplify it if not, then update this check.
            """)
        }
    }
}

@main
private struct MacOSSurfaceChecksRunner {
    static func main() {
        do {
            try runChecks()
            print("macOS surface checks passed (\(checksRun)/\(checksRun))")
        } catch let failure as CheckFailure {
            fputs("macOS surface check failed: \(failure.message)\n", stderr)
            exit(1)
        } catch {
            fputs("macOS surface checks failed: \(error)\n", stderr)
            exit(1)
        }
    }
}
#endif

